#!/usr/bin/env python3
"""
bulwark-wifi-proxy — runs inside sys-net VM.

Bridges iwd (D-Bus) to the host BulwarkOS desktop via a virtio-serial
character device. Protocol: newline-delimited JSON.

Commands arrive from host → dispatched to iwd → response sent back.
Unsolicited events (connected/disconnected) are also emitted.

Installed at: /usr/local/bin/bulwark-wifi-proxy
Requires:     python3, python3-dbus, iwd
"""

import json, os, sys, threading, time, logging, select, signal

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [proxy] %(levelname)s %(message)s",
    stream=sys.stderr,
)
log = logging.getLogger("proxy")

VIRTIO_PORT = "/dev/virtio-ports/org.bulwarkos.wifi"
IWD_BUS     = "net.connman.iwd"
IWD_STATION = "net.connman.iwd.Station"
IWD_NETWORK = "net.connman.iwd.Network"

try:
    import dbus
    import dbus.mainloop.glib
    HAS_DBUS = True
except ImportError:
    HAS_DBUS = False
    log.warning("python3-dbus not available — iwd calls will fail")


class IwdBridge:
    """Thin wrapper around iwd D-Bus API."""

    def __init__(self):
        self._bus          = None
        self._station      = None
        self._station_path = None

    def connect_dbus(self) -> bool:
        if not HAS_DBUS:
            return False
        try:
            dbus.mainloop.glib.DBusGMainLoop(set_as_default=True)
            self._bus = dbus.SystemBus()
            self._find_station()
            return True
        except Exception as e:
            log.error(f"D-Bus connect failed: {e}")
            return False

    def _find_station(self):
        try:
            mgr = dbus.Interface(
                self._bus.get_object(IWD_BUS, "/"),
                "org.freedesktop.DBus.ObjectManager",
            )
            for path, ifaces in mgr.GetManagedObjects().items():
                if IWD_STATION in ifaces:
                    self._station_path = str(path)
                    self._station = dbus.Interface(
                        self._bus.get_object(IWD_BUS, path), IWD_STATION
                    )
                    log.info(f"Station: {path}")
                    return
            log.warning("No iwd Station — WiFi adapter present?")
        except Exception as e:
            log.error(f"Station search failed: {e}")

    def _props(self, path, iface) -> dict:
        try:
            pi = dbus.Interface(
                self._bus.get_object(IWD_BUS, path),
                "org.freedesktop.DBus.Properties",
            )
            return dict(pi.GetAll(iface))
        except Exception:
            return {}

    def scan(self) -> tuple[bool, str]:
        if not self._station:
            self._find_station()
        if not self._station:
            return False, "No wireless station"
        try:
            self._station.Scan()
            return True, "Scan initiated"
        except Exception as e:
            return False, str(e)

    def list_networks(self) -> list:
        if not self._station:
            self._find_station()
        if not self._station:
            return []
        try:
            result = []
            for net_path, strength in self._station.GetOrderedNetworks():
                p = self._props(str(net_path), IWD_NETWORK)
                result.append({
                    "ssid":        str(p.get("Name", "")),
                    "security":    str(p.get("Type", "open")),
                    "connected":   bool(p.get("Connected", False)),
                    "strength_dbm": int(strength),
                    "path":        str(net_path),
                })
            return result
        except Exception as e:
            log.error(f"list_networks: {e}")
            return []

    def connect_network(self, ssid: str, passphrase: str | None) -> tuple[bool, str]:
        if not self._station:
            self._find_station()
        if not self._station:
            return False, "No wireless station"
        try:
            target = None
            for net_path, _ in self._station.GetOrderedNetworks():
                p = self._props(str(net_path), IWD_NETWORK)
                if str(p.get("Name", "")) == ssid:
                    target = str(net_path)
                    break
            if not target:
                return False, f"'{ssid}' not found — scan first"

            if passphrase:
                # Write PSK file so iwd can authenticate
                self._write_psk(ssid, passphrase)

            net = dbus.Interface(
                self._bus.get_object(IWD_BUS, target), IWD_NETWORK
            )
            net.Connect()
            return True, f"Connecting to '{ssid}'"
        except Exception as e:
            return False, str(e)

    def _write_psk(self, ssid: str, passphrase: str):
        """Write iwd PSK provisioning file for WPA2/WPA3 networks."""
        psk_dir = "/var/lib/iwd"
        os.makedirs(psk_dir, exist_ok=True)
        # Sanitise SSID for use as filename
        safe = ssid.replace("/", "_").replace("\x00", "")
        path = f"{psk_dir}/{safe}.psk"
        with open(path, "w") as f:
            f.write(f"[Security]\nPassphrase={passphrase}\n")
        os.chmod(path, 0o600)
        log.info(f"Wrote PSK file: {path}")

    def disconnect(self) -> tuple[bool, str]:
        if not self._station:
            return False, "No station"
        try:
            self._station.Disconnect()
            return True, "Disconnected"
        except Exception as e:
            return False, str(e)

    def status(self) -> dict:
        if not self._station:
            return {"state": "unavailable", "ssid": ""}
        p     = self._props(self._station_path, IWD_STATION)
        state = str(p.get("State", "unknown"))
        ssid  = ""
        cn    = p.get("ConnectedNetwork")
        if cn:
            np   = self._props(str(cn), IWD_NETWORK)
            ssid = str(np.get("Name", ""))
        return {"state": state, "ssid": ssid}

    def forget_network(self, ssid: str) -> tuple[bool, str]:
        """Remove stored credentials for a network."""
        safe = ssid.replace("/", "_").replace("\x00", "")
        removed = False
        for ext in (".psk", ".8021x", ".open"):
            path = f"/var/lib/iwd/{safe}{ext}"
            if os.path.exists(path):
                os.unlink(path)
                removed = True
        return (True, f"Forgotten '{ssid}'") if removed else (False, f"No credentials stored for '{ssid}'")


class WifiProxy:
    def __init__(self):
        self._iwd  = IwdBridge()
        self._port = None
        self._lock = threading.Lock()

    def _send(self, obj: dict):
        try:
            data = (json.dumps(obj) + "\n").encode()
            with self._lock:
                self._port.write(data)
                self._port.flush()
        except OSError as e:
            log.error(f"Write error: {e}")

    def _event(self, name: str, **kw):
        self._send({"event": name, **kw})

    def _dispatch(self, cmd: dict) -> dict:
        cid  = cmd.get("id", 0)
        name = cmd.get("cmd", "")

        if name == "ping":
            return {"id": cid, "ok": True, "pong": True}
        elif name == "scan":
            ok, msg = self._iwd.scan()
            return {"id": cid, "ok": ok, "msg": msg}
        elif name == "list_networks":
            return {"id": cid, "ok": True, "networks": self._iwd.list_networks()}
        elif name == "connect":
            ok, msg = self._iwd.connect_network(
                cmd.get("ssid", ""), cmd.get("passphrase")
            )
            return {"id": cid, "ok": ok, "msg": msg}
        elif name == "disconnect":
            ok, msg = self._iwd.disconnect()
            return {"id": cid, "ok": ok, "msg": msg}
        elif name == "status":
            st = self._iwd.status()
            return {"id": cid, "ok": True, **st}
        elif name == "forget":
            ok, msg = self._iwd.forget_network(cmd.get("ssid", ""))
            return {"id": cid, "ok": ok, "msg": msg}
        else:
            return {"id": cid, "ok": False, "msg": f"Unknown command: {name}"}

    def _poll_state(self):
        last = None
        while True:
            time.sleep(3)
            try:
                st = self._iwd.status()
                sig = (st["state"], st["ssid"])
                if sig != last:
                    last = sig
                    if st["state"] == "connected":
                        self._event("connected", ssid=st["ssid"])
                    elif st["state"] in ("disconnected", "unknown"):
                        self._event("disconnected")
                    else:
                        self._event("state_changed", state=st["state"])
            except Exception:
                pass

    def run(self):
        log.info(f"Waiting for {VIRTIO_PORT}")
        while not os.path.exists(VIRTIO_PORT):
            time.sleep(1)

        log.info("Connecting to iwd D-Bus")
        self._iwd.connect_dbus()

        self._port = open(VIRTIO_PORT, "r+b", buffering=0)
        log.info("Port open — polling state")

        threading.Thread(target=self._poll_state, daemon=True).start()

        log.info("Ready")
        buf = b""
        while True:
            try:
                r, _, _ = select.select([self._port], [], [], 5.0)
                if not r:
                    continue
                chunk = self._port.read(4096)
                if not chunk:
                    time.sleep(2)
                    continue
                buf += chunk
                while b"\n" in buf:
                    line, buf = buf.split(b"\n", 1)
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        cmd  = json.loads(line)
                        resp = self._dispatch(cmd)
                        self._send(resp)
                    except json.JSONDecodeError as e:
                        self._send({"ok": False, "msg": f"JSON error: {e}"})
            except OSError as e:
                log.error(f"Port read error: {e}")
                time.sleep(2)


def main():
    signal.signal(signal.SIGTERM, lambda *_: sys.exit(0))
    WifiProxy().run()


if __name__ == "__main__":
    main()
